#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=8

# Paths and shared settings for every stage.
BACKEND_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_DIR="$(cd "$BACKEND_DIR/.." && pwd)"
WRANGLER_TOML="$BACKEND_DIR/wrangler.toml"
BACKEND_KT="$REPO_DIR/site/src/jsMain/kotlin/dev/ritwik/iama/data/Backend.kt"
PLACEHOLDER_DB_ID="00000000-0000-0000-0000-000000000000"
export WRANGLER_SEND_METRICS=false
cd "$BACKEND_DIR"

wr() { npx --yes wrangler "$@"; }

# kt_set CONST VALUE rewrites `private const val CONST = "…"` in Backend.kt (BSD/GNU safe via perl).
kt_set() {
  KT_VALUE="$2" perl -pi -e "s/(private const val $1 = \")[^\"]*(\")/\${1}\$ENV{KT_VALUE}\${2}/" "$BACKEND_KT"
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$1" "${BACKEND_KT#"$REPO_DIR/"}"
}
kt_get() { perl -ne "print \$1 if /private const val $1 = \"([^\"]*)\"/" "$BACKEND_KT"; }

# has_secret NAME → success if the deployed Worker already has that secret.
has_secret() { wr secret list --format json 2>/dev/null | grep -q "\"$1\""; }

banner "IAmA backend: Cloudflare Worker + D1 + Turnstile"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Prerequisites"
say "Checking Node.js and installing the backend's dependencies (wrangler, tests)."
if ! command -v node >/dev/null 2>&1; then
  warn "Node.js isn't installed. Install Node 20+ (https://nodejs.org) and re-run."
  exit 1
fi
node_major=$(node -p 'process.versions.node.split(".")[0]')
(( node_major >= 20 )) || warn "Node $(node -v) detected; wrangler needs Node 20 or newer."
npm install --no-audit --no-fund
printf '  %s✓%s dependencies installed\n' "$GREEN" "$RESET"
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Sign in to Cloudflare"
if wr whoami 2>/dev/null | grep -qi "associated with the email"; then
  note "Already signed in:"
  wr whoami 2>/dev/null | grep -i "email" || true
else
  say "You need a free Cloudflare account. If you don't have one yet:"
  open_url "https://dash.cloudflare.com/sign-up"
  step "Sign up (the Free plan is all this needs), verify your email, then come back here."
  pause "Press Enter when you have an account"
  say "Now wrangler will open your browser to authorise this machine."
  step "Click 'Allow' on the Cloudflare page, then return to this terminal."
  wr login
  wr whoami | grep -i "email" || true
fi
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Create the database"
current_id=$(perl -ne 'print $1 if /^database_id = "([^"]*)"/' "$WRANGLER_TOML")
if [[ -n "$current_id" && "$current_id" != "$PLACEHOLDER_DB_ID" ]]; then
  note "wrangler.toml already points at D1 database $current_id; skipping."
else
  say "Creating a D1 (SQLite) database called 'iama' on your account."
  wr d1 create iama 2>&1 | tee /tmp/iama-d1-create.log || true
  db_id=$(grep -Eo '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}' /tmp/iama-d1-create.log | head -n1 || true)
  if [[ -z "$db_id" ]]; then
    note "Looking up an existing 'iama' database instead…"
    db_id=$(wr d1 list --json 2>/dev/null | node -e 'let s="";process.stdin.on("data",d=>s+=d).on("end",()=>{const d=JSON.parse(s).find(x=>x.name==="iama");process.stdout.write(d?d.uuid:"")})' || true)
  fi
  rm -f /tmp/iama-d1-create.log
  if [[ -z "$db_id" ]]; then
    warn "Couldn't find the database id. Run 'npx wrangler d1 list' and paste the iama UUID."
    ask db_id "Database id:"
  fi
  DB_ID="$db_id" perl -pi -e 's/^database_id = "[^"]*"/database_id = "$ENV{DB_ID}"/' "$WRANGLER_TOML"
  printf '  %s✓ wrote%s database_id → backend/wrangler.toml\n' "$GREEN" "$RESET"
fi
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Apply the schema"
say "Creating the tables (visitor counter, daily visit hashes, guestbook notes)."
note "Safe to re-run: already-applied migrations are skipped."
wr d1 migrations apply iama --remote
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Deploy the Worker"
say "Publishing the API to Cloudflare on a free workers.dev URL."
note "First deploy on a new account needs a one-time workers.dev subdomain; the wizard"
note "opens the page for it if Cloudflare asks."
API_URL=""
for attempt in 1 2 3; do
  # Output is captured to find the URL, which makes wrangler non-interactive; so the
  # subdomain prompt can't be answered here, and we route that through the dashboard instead.
  wr deploy 2>&1 | tee /tmp/iama-deploy.log || true
  API_URL=$(grep -Eo 'https://[a-z0-9.-]+\.workers\.dev' /tmp/iama-deploy.log | head -n1 || true)
  [[ -n "$API_URL" ]] && break
  if grep -q "register a workers.dev subdomain" /tmp/iama-deploy.log; then
    onboarding=$(grep -Eo 'https://dash\.cloudflare\.com/[^ ]*/workers/onboarding' /tmp/iama-deploy.log | head -n1 || true)
    printf '\n'
    warn "Your account needs a workers.dev subdomain first (one-time)."
    open_url "${onboarding:-https://dash.cloudflare.com/?to=/:account/workers/onboarding}"
    step "Choose a subdomain (e.g. 'ritwik'); the API will live at iama-api.<it>.workers.dev."
    step "Confirm it on that page. It can take a minute to become active."
    pause "Press Enter once it's registered, and the wizard will retry the deploy"
  else
    warn "Deploy didn't finish (see the output above)."
    confirm "Retry the deploy?" || break
  fi
done
rm -f /tmp/iama-deploy.log
if [[ -z "$API_URL" ]]; then
  warn "Couldn't spot the workers.dev URL in the output above."
  ask API_URL "Paste the Worker URL (https://iama-api.<you>.workers.dev):"
fi
API_URL="${API_URL%/}"
kt_set PROD_API "$API_URL"
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Turnstile spam check"
existing_key=$(kt_get PROD_TURNSTILE_SITE_KEY)
if [[ -n "$existing_key" ]] && has_secret TURNSTILE_SECRET && ! confirm "Turnstile is already configured. Replace its keys?"; then
  note "Keeping the existing Turnstile keys."
else
  say "Turnstile is Cloudflare's invisible captcha; it keeps bots out of the guestbook."
  open_url "https://dash.cloudflare.com/?to=/:account/turnstile"
  step "Click 'Add widget' (button labels may differ slightly)."
  step "Name it: iama-guestbook"
  step "Hostnames: add  antimkhel.github.io  and  localhost"
  step "Widget mode: Managed. Pre-clearance: No. Then create it."
  step "The next page shows a Site Key and a Secret Key."
  ask TURNSTILE_SITE_KEY "Paste the Site Key (public):"
  kt_set PROD_TURNSTILE_SITE_KEY "$TURNSTILE_SITE_KEY"
  ask_secret TURNSTILE_SECRET "Paste the Secret Key (hidden):"
  printf '%s' "$TURNSTILE_SECRET" | wr secret put TURNSTILE_SECRET >/dev/null
  unset TURNSTILE_SECRET
  printf '  %s✓ set%s Worker secret TURNSTILE_SECRET\n' "$GREEN" "$RESET"
fi
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Admin token & privacy salt"
if ! has_secret HASH_SALT; then
  openssl rand -hex 32 | tr -d '\n' | wr secret put HASH_SALT >/dev/null
  printf '  %s✓ set%s Worker secret HASH_SALT (random, never shown)\n' "$GREEN" "$RESET"
else
  note "HASH_SALT already set; keeping it (changing it would re-count today's visitors)."
fi
if has_secret ADMIN_TOKEN && ! confirm "ADMIN_TOKEN already exists. Generate a new one?"; then
  note "Keeping the current ADMIN_TOKEN (the one in your password manager)."
else
  admin_token=$(openssl rand -hex 24)
  printf '%s' "$admin_token" | wr secret put ADMIN_TOKEN >/dev/null
  printf '  %s✓ set%s Worker secret ADMIN_TOKEN\n\n' "$GREEN" "$RESET"
  warn "Copy this into your password manager NOW. It won't be shown again:"
  printf '\n      %s%s%s\n\n' "$BOLD" "$admin_token" "$RESET"
  note "You'll paste it once at https://antimkhel.github.io/IAmA/admin to approve notes."
  unset admin_token
  pause "Press Enter once it's saved"
fi
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Smoke test & next steps"
API_URL=$(kt_get PROD_API)
say "Calling $API_URL/stats as the live site would…"
stats=$(curl -s -m 15 -H "Origin: https://antimkhel.github.io" "$API_URL/stats" || true)
cors=$(curl -s -m 15 -o /dev/null -D - -H "Origin: https://antimkhel.github.io" "$API_URL/stats" | grep -i '^access-control-allow-origin' || true)
if [[ "$stats" == *visitors* ]]; then
  printf '  %s✓%s API answered: %s\n' "$GREEN" "$RESET" "$stats"
else
  warn "Unexpected response: ${stats:-<none>} (a new workers.dev subdomain can take a minute; re-run this stage later)"
fi
[[ -n "$cors" ]] && printf '  %s✓%s CORS allows the portfolio origin\n' "$GREEN" "$RESET" || warn "No CORS header seen for https://antimkhel.github.io"
printf '\n'
say "Changed in the repo (no secrets):"
note "  backend/wrangler.toml        database_id"
note "  site/…/data/Backend.kt       PROD_API, PROD_TURNSTILE_SITE_KEY"
say "Next: tell Claude \"backend is set up\". It will test against the live API, commit"
say "those two files and, when you say so, push to deploy the site."
pause "Press Enter to finish"

finish
}

run_wizard "$@"; exit
